// Detect bank type and parse transaction from notification email
const item = $input.first();
const { from, subject, text, html } = item.json;

const body = (text || html || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
const sender = (from || '').toLowerCase();
const subjectLow = (subject || '').toLowerCase();

// ── Helper functions ──────────────────────────────────────────────────────────
function parseAmount(str) {
  // Matches: Rp 1.234.567,89 / Rp1,234,567.89 / IDR 1234567
  const cleaned = str.replace(/[^\d,\.]/g, '');
  // Remove thousand separators (dots before 3-digit groups at end)
  const normalized = cleaned.replace(/\.(\d{3})([\.,]|$)/g, '$1$2').replace(',', '.');
  return parseFloat(normalized) || 0;
}

function extractAmount(text) {
  const patterns = [
    /Rp\.?\s*([\d.,]+)/i,
    /IDR\s*([\d.,]+)/i,
    /nominal[:\s]+Rp\.?\s*([\d.,]+)/i,
    /amount[:\s]+Rp\.?\s*([\d.,]+)/i,
    /sebesar\s+Rp\.?\s*([\d.,]+)/i,
  ];
  for (const p of patterns) {
    const m = text.match(p);
    if (m) return parseAmount(m[1]);
  }
  return 0;
}

function extractMerchant(text, bankType) {
  const patterns = {
    BCA: [
      /(?:di|pada|to|merchant)[:\s]+([A-Z0-9 \-\/&.']+?)(?:\n|\r|\s{2,}|Tgl|Tanggal|Rp)/i,
      /keterangan[:\s]+([^\n\r]{3,80})/i,
    ],
    Jenius: [
      /(?:at|di)\s+([A-Z0-9 \-\/&.']+?)(?:\n|\r|\s{2,}|\.\s)/i,
      /merchant[:\s]+([^\n\r]{3,80})/i,
    ],
    UOB: [
      /(?:at|merchant)[:\s]+([A-Z0-9 \-\/&.'*]+?)(?:\n|\r|\s{2,}|on\s)/i,
    ],
    BRI: [
      /(?:di|merchant|kepada)[:\s]+([A-Z0-9 \-\/&.']+?)(?:\n|\r|\s{2,}|Rp)/i,
    ],
  };
  const bankPatterns = patterns[bankType] || [];
  for (const p of bankPatterns) {
    const m = text.match(p);
    if (m) return m[1].trim();
  }
  return 'Unknown Merchant';
}

function extractDate(text) {
  const patterns = [
    // DD/MM/YYYY HH:MM
    /(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})(?:\s+(\d{1,2}):(\d{2}))?/,
    // DD MMM YYYY
    /(\d{1,2})\s+(Jan|Feb|Mar|Apr|Mei|Jun|Jul|Agu|Sep|Okt|Nov|Des|May|Aug|Oct)\s+(\d{4})/i,
    // YYYY-MM-DD
    /(\d{4})-(\d{2})-(\d{2})/,
  ];
  const monthMap = {
    jan:1, feb:2, mar:3, apr:4, mei:5, may:5, jun:6,
    jul:7, agu:8, aug:8, sep:9, okt:10, oct:10, nov:11, des:12,
  };
  for (const p of patterns) {
    const m = text.match(p);
    if (m) {
      try {
        if (m[0].match(/\d{4}-\d{2}-\d{2}/)) return new Date(m[0]).toISOString();
        if (typeof m[3] === 'string' && isNaN(Number(m[3]))) {
          // DD MMM YYYY
          const month = monthMap[(m[3] || '').toLowerCase().slice(0,3)];
          if (month) return new Date(Number(m[4]), month - 1, Number(m[1])).toISOString();
        }
        const [, d, mo, y, h = '0', min = '0'] = m;
        return new Date(Number(y), Number(mo) - 1, Number(d), Number(h), Number(min)).toISOString();
      } catch {
        // fall through
      }
    }
  }
  return new Date().toISOString();
}

function detectPaymentType(text) {
  const creditKeywords = /kredit|credit card|kartu kredit|cc|cicilan/i;
  const debitKeywords = /debit|tabungan|rekening|transfer|tarik tunai/i;
  if (creditKeywords.test(text)) return 'credit';
  if (debitKeywords.test(text)) return 'debit';
  return 'debit'; // default
}

// ── Detect bank ───────────────────────────────────────────────────────────────
let bankType = null;
if (sender.includes('bca') || subjectLow.includes('bca') || body.includes('BCA')) {
  bankType = 'BCA';
} else if (sender.includes('jenius') || subjectLow.includes('jenius') || body.includes('Jenius')) {
  bankType = 'Jenius';
} else if (sender.includes('uob') || subjectLow.includes('uob') || body.includes('UOB')) {
  bankType = 'UOB';
} else if (sender.includes('bri') || subjectLow.includes('bri') || body.includes('BRI')) {
  bankType = 'BRI';
}

if (!bankType) {
  return [{ json: { skip: true, reason: 'Not a supported bank notification' } }];
}

const amount = extractAmount(body);
if (amount <= 0) {
  return [{ json: { skip: true, reason: 'No valid amount found', bankType, body: body.slice(0, 200) } }];
}

const merchant = extractMerchant(body, bankType);
const transactionDate = extractDate(body);
const paymentType = detectPaymentType(body);

return [{
  json: {
    skip: false,
    bankType,
    paymentType,
    merchant,
    amount,
    currency: 'IDR',
    transactionDate,
    _debug: { subject, sender: from, bodySnippet: body.slice(0, 300) },
  }
}];
